# Simplified Anserini-style RM3 on the toy corpus
top = {"d1": 1.07, "d4": 0.67}            # fbDocs = 2, BM25 scores
docs = {"d1": "car repair shop brakes".split(),
        "d4": "car rental airport deals".split()}
fb_terms, orig_weight = 5, 0.5

weights = {}
for d, score in top.items():
    for t in set(docs[d]):
        p = docs[d].count(t) / len(docs[d])   # P(t | d)
        weights[t] = weights.get(t, 0) + p * score

best = sorted(weights.items(), key=lambda kv: (-kv[1], kv[0]))[:fb_terms]
z = sum(w for _, w in best)
rm = {t: w / z for t, w in best}              # relevance model

query = {"car": 0.5, "repair": 0.5}           # original, L1-normalized
final = {t: orig_weight * query.get(t, 0) + (1 - orig_weight) * rm.get(t, 0)
         for t in set(query) | set(rm)}
for t, w in sorted(final.items(), key=lambda kv: (-kv[1], kv[0])):
    print(t, round(w, 3))
